        idx_n = offs_b_n[None, :]
        xindex = idx_n + 10*idx_m
        b = tl.load(B + ((tl.broadcast_to(idx_m + 1920*idx_n, [BLOCK_K, BLOCK_N])).broadcast_to(xindex.shape)))


